# Feature computation including isolated-single-cell colors within zone (component of size 1 globally? etc.)
def featdict(I,rz,cz):
    cnt=Counter(x for rr in I for x in rr)
    cells=[]
    for r_ in rz:
        for c_ in cz:
            v=I[r_][c_]
            if v!=0: cells.append(v)
    f=Counter(cells)
    # per-color global count
    gc={v:cnt[v] for v in f}
    # local component sizes: BFS within zone over nonzero adjacency
    seen=set(); comps=[]
    for idx,(r_,c_) in enumerate([(rr,kk) for rr in rz for kk in cz]):
        if (r_,c_) in seen: continue
        st=[(r_,c_)]; comp=[]
        while st:
            a,b=st.pop()
            if (a,b) in seen: continue
            seen.add((a,b)); comp.append((a,b))
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                x,y=a+dr,b+dc
                if x in rz and y in cz and I[x][y]!=0: st.append((x,y))
        comps.append(comp)
    # min comp size among colors present, max
    csizes=[len(c) for c in comps]
    return dict(nz=len(cells),zeros=len(rz)*len(cz)-len(cells),ndist=len(f),
                ncomp=len(comps),mincomp=min(csizes),maxcomp=max(csizes),sumcomp=sum(csizes),
                isolates=sum(1 for s in csizes if s==1),
                g1=sum(gc[v] for v in f if gc[v]==1),g2=sum(gc[v] for v in f if gc[v]==2),
                ndistinct=ndist, nzcells=nz, dommax=max(gc.values()) if gc else 0, totcells=len(rz)*len(cz))

